      applyActivitiesByFilter: assignActivitiesByFilter(
        filterId: $filterId,
        simulationDatasetId: $simulationDatasetId,
        seqId: $seqId,
        timeRangeEnd: $timeRangeEnd,
        timeRangeStart: $timeRangeStart
