query CheckConstraints($planId: Int!, $force: Boolean!) {
      constraintRunResponses: constraintViolations(planId: $planId, force: $force) {
        requestId
        constraintsRun {
          success
          constraintId
          constraintInvocationId
          constraintName
          constraintRevision
          results {
            resourceIds
            gaps {
              end
              start
            }
            violations {
              message
              activityInstanceIds
              windows {
                end
                start
              }
            }
          }
          errors {
            message
            stack
            location {
              column
              line
            }
          }
        }
      }
    }

